  get startingWeaponOptions():SpaceUpgrade[]{const pool=[this.startingWeaponOption('laser','Laser Array','Reliable piercing beams. Upgrade its damage, speed, salvo, range, and critical hits.'),this.startingWeaponOption('missile','Missile Rack','Heavy homing rockets with splash damage. Upgrade their damage, speed, salvo, range, and bounces.'),this.startingWeaponOption('plasma','Plasma Cannon','Fast plasma bolts. Upgrade their damage, speed, salvo, range, and critical hits.'),this.startingWeaponOption('drone','Combat Drone','Autonomous drones that hunt bugs. Upgrade their damage, speed, salvo, range, and critical hits.'),this.startingWeaponOption('rail','Railgun','An extremely fast hail of tiny spikes. Upgrade their damage, speed, salvo, range, and critical hits.'),this.startingWeaponOption('flak','Flak Cannon','A short-range scattergun with splash damage. Upgrade its damage, speed, salvo, range, and critical hits.'),this.startingWeaponOption('tesla','Chain Lightning Gun','Lightning arcs that chain between clustered enemies. Upgrade its damage, speed, jumps, range, and critical hits.'),this.startingWeaponOption('chem','Chem Cloud','Lobs corrosive globs that burst into lingering acid clouds. Upgrade its damage, speed, globs, duration, and critical hits.')];return pool.sort(()=>Math.random()-.5).slice(0,3);}
