  private drawShip(ctx:CanvasRenderingContext2D,x:number,y:number,z:number){if(this.playerSpriteReady&&this.playerSprite){const fw=this.playerSprite.naturalWidth/4,fh=this.playerSprite.naturalHeight/4,dw=z*2.15,dh=dw*(fh/fw);ctx.save();ctx.imageSmoothingEnabled=false;ctx.shadowBlur=16;ctx.shadowColor='#55dfff';ctx.drawImage(this.playerSprite,(Math.floor(performance.now()/140)%4)*fw,3*fh,fw,fh,x-dw/2,y-dh/2,dw,dh);ctx.restore();this.drawShield(ctx,x,y,z);return;}ctx.save();ctx.translate(x,y);ctx.fillStyle='#b9d9e8';ctx.strokeStyle='#66ddff';ctx.beginPath();ctx.moveTo(0,-z*1.35);ctx.lineTo(z,z*.55);ctx.lineTo(0,z*.8);ctx.lineTo(-z,z*.55);ctx.closePath();ctx.fill();ctx.stroke();if(this.timers.shield>this.stats.shieldPulseInterval-this.stats.shieldVisibleFor){ctx.beginPath();ctx.strokeStyle='#55eaff';ctx.arc(0,0,z*(1.45+this.stats.shieldRadius*4),0,Math.PI*2);ctx.stroke();}ctx.restore();}
