  private drawPlasma(ctx:CanvasRenderingContext2D,s:SpaceProjectile,w:number,h:number){const px=s.x*w,py=s.y*h,ang=Math.atan2(s.vy,s.vx),r=Math.max(4,s.radius*w);ctx.save();ctx.translate(px,py);ctx.rotate(ang);ctx.shadowBlur=18;ctx.shadowColor='#ff66dd';ctx.fillStyle='rgba(255,102,221,.35)';ctx.beginPath();ctx.ellipse(0,0,r*2.2,r*.9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff9df0';ctx.beginPath();ctx.ellipse(0,0,r*1.4,r*.55,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#ffffff';ctx.beginPath();ctx.ellipse(0,0,r*.7,r*.28,0,0,Math.PI*2);ctx.fill();ctx.restore();}
  private drawMissile(ctx:CanvasRenderingContext2D,s:SpaceProjectile,w:number,h:number){const px=s.x*w,py=s.y*h,ang=Math.atan2(s.vy,s.vx),r=Math.max(3.5,s.radius*w);ctx.save();ctx.translate(px,py);ctx.rotate(ang);ctx.shadowBlur=16;ctx.shadowColor='#ff9d4d';const b=r;ctx.fillStyle='#e8e4d8';ctx.strokeStyle='#8a8578';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(b*1.6,0);ctx.lineTo(-b,b*.62);ctx.lineTo(-b*.7,0);ctx.lineTo(-b,-b*.62);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#c93a2c';ctx.beginPath();ctx.moveTo(0,-b*.3);ctx.lineTo(-b*.92,-b*.3);ctx.lineTo(-b*.55,0);ctx.lineTo(-b*.92,b*.3);ctx.lineTo(0,b*.3);ctx.closePath();ctx.fill();const flick=.82+Math.sin(performance.now()/16)*.16;ctx.fillStyle='#ffe08a';ctx.shadowBlur=12;ctx.beginPath();ctx.moveTo(-b*.7,0);ctx.lineTo(-b-b*1.35*flick,0);ctx.lineTo(-b*.55,-b*.26);ctx.closePath();ctx.fill();ctx.fillStyle='#6dd5ff';ctx.shadowBlur=0;ctx.beginPath();ctx.arc(-b*.08,0,b*.32,0,Math.PI*2);ctx.fill();ctx.restore();}
