    for(let i=0;i<unitCount-1;i++){ctx.beginPath();ctx.moveTo(BUG_NODE_XY[i*2],BUG_NODE_XY[i*2+1]);ctx.lineTo(BUG_NODE_XY[i*2+2],BUG_NODE_XY[i*2+3]);ctx.stroke();}
    ctx.globalAlpha=1;ctx.shadowBlur=0;
